/*
 * The Quartermaster — level-up gear mail.
 *
 * Alonecraft runs 10x XP but leaves loot and gold rates at 1x, so a character
 * levels roughly ten times faster than equipment arrives and simply outruns
 * their gear.  On each level-up the Quartermaster mails three items, each in a
 * DIFFERENT equipment slot, chosen for the player's class and active spec.
 *
 * Everything expensive happens offline.  tools/gen_quartermaster_pool.py scores
 * every upgrade variant (entry >= 1000000, generated by gen_item_variants.py)
 * for each class/talent-tree/level/slot and writes the top few into
 * `alonecraft_quartermaster_pool`.  All that is left here is a weighted random
 * pick from an in-memory copy of that table.
 *
 * THE AFFIX IS PART OF THE ANSWER, not a runtime roll.  A vanilla green's whole
 * identity is often its affix -- "of the Eagle" is a caster item and "of the
 * Bear" is a tank item off the SAME base cloak -- so the generator picks the
 * affix that suits the archetype and stores the concrete id in `rand_prop`.
 * This file just applies it.  Item::CreateItem never rolls one on its own.
 *
 *   rand_prop = 0   fixed-stat item
 *             > 0   ItemRandomProperties.ID
 *             < 0   -ItemRandomSuffix.ID  (rescales off the item's own ItemLevel)
 *
 * Two things here are load-bearing and easy to get wrong:
 *
 *   1. The pool is keyed by TALENT TREE, not by spec slot.  GetActiveSpec()
 *      returns a slot index 0..7 (Alonecraft.ExtraSpec.MaxSpecs), which says
 *      nothing about what the spec IS -- it is a save-file number.  The tree
 *      has to be read from that slot's talents; see GetActiveTree below.
 *
 *   2. Picks are made per SLOT GROUP, not per InventoryType.  Choosing three
 *      distinct InventoryTypes would cheerfully mail a two-hander and a
 *      main-hand sword, or a chest and a robe -- the same body slot twice.
 *
 * The feature starts at level 10 (Alonecraft.Quartermaster.MinLevel) because
 * the level-5 variant tier is only 32 items across 4 slots; half the classes
 * cannot fill three distinct slots from it at all.  See the conf file.
 */

#include "CharacterCache.h"
#include "Chat.h"
#include "CommandScript.h"
#include "Config.h"
#include "DBCStores.h"
#include "DatabaseEnv.h"
#include "Item.h"
#include "Log.h"
#include "Mail.h"
#include "MultiSpec.h"
#include "ObjectAccessor.h"
#include "ObjectMgr.h"
#include "Player.h"
#include "Random.h"
#include "ScriptMgr.h"
